package com.pillar.resources; import com.pillar.*; import java.util.*; public class Resource { private final PillarClient client; private final String path; public Resource(PillarClient c,String p){client=c;path=p;} public Map retrieve(String id){return client.request("GET", path+"/"+id, null, null);} public Map create(Map body, PillarClient.RequestOptions opts){return client.request("POST", path, body, opts);} public Page<Map> list(){ return new Page<>((java.util.List<Map>)client.request("GET", path, null, null).getOrDefault("data", java.util.List.of()), false, null, c -> list()); } }
